export function encodeEsse3CacheInfo(value: Esse3CacheInfo): JsonObject {
  return {
    "httpCacheEnable": value.httpCacheEnable,
    "serverCacheEnable": value.serverCacheEnable,
  };
}

export interface Esse3JWTModel {
  /** jwt */
  jwt: string | null;
}

/** Decodes a {@link Esse3JWTModel}; `undefined` when `json` isn't an object. */
export function decodeEsse3JWTModel(json: unknown): Esse3JWTModel | undefined {
  const object = asJsonObject(json);
  if (object === undefined) return undefined;
  return {
    jwt: decodeString(object["jwt"]) ?? null,
  };
}

export function encodeEsse3JWTModel(value: Esse3JWTModel): JsonObject {
  return {
    "jwt": value.jwt,
  };
}
